generated_pydough:
characteristic_counts = product_characteristic.CALCULATE(
    characteristic_name=characteristic.characteristic_name
).PARTITION(
    name="characteristics_group",
    by=characteristic_name
).CALCULATE(
    characteristic_name=characteristic_name,
    char_count=COUNT(product_characteristic)
)

most_common_characteristic = characteristic_counts.TOP_K(
    1,
    by=char_count.DESC()
).CALCULATE(
    characteristic_name=characteristic_name
)

most_enrolled_course_name = Courses.CALCULATE(
    course_name_aliased=course_name,
    num_students_enrolled=COUNT(student_enrolment_course.student_course_id)
).TOP_K(1, by=(num_students_enrolled.DESC(), course_name_aliased.DESC())
).CALCULATE(course_name_result=course_name_aliased)

average_ratings_for_filtered_movies = movies.WHERE(
    HASNOT(ratings.WHERE(reviewer.name == 'Brittany Harris')) & HAS(ratings)
).CALCULATE(
    movie_id=mid,
    average_rating=AVG(ratings.stars)
)

shop_with_greatest_quantity = shops.CALCULATE(
    shop_name=shop_name,
    total_stock_quantity=SUM(stocks.quantity)
).TOP_K(1, by=total_stock_quantity.DESC()).CALCULATE(
    shop_name=shop_name
)

most_papers_institution = insts.CALCULATE(
    inst_name=name,
    paper_count=COUNT(authorships.paper)
).TOP_K(1, by=paper_count.DESC()).CALCULATE(
    inst_name=inst_name
)

lowest_cost_treatment_type_description = dog_kennels.treatment_type.CALCULATE(
    treatment_type_description=treatment_type_description,
    total_cost=SUM(treatment.cost_of_treatment)
).TOP_K(1, by=total_cost.ASC()).CALCULATE(
    description=treatment_type_description
)

global_average_savings = GRAPH.CALCULATE(
    avg_savings_balance=AVG(SAVINGS.balance)
)

result = ACCOUNTS.WHERE(
    ACCOUNTS.saving.balance > global_average_savings.SINGULAR().avg_savings_balance
).CALCULATE(
    account_name=name,
    total_balance=ACCOUNTS.checkings.balance + ACCOUNTS.saving.balance
)

most_common_apartment_type_code = apartment.WHERE(
    bathroom_count > 1
).PARTITION(
    name="apartment_types_group", by=apt_type_code
).CALCULATE(
    # Select the apt_type_code (partition key) and count apartments within each group
    apt_type_code=apt_type_code,
    num_apartments=COUNT(apartment)
).TOP_K(
    1, by=(num_apartments.DESC(), apt_type_code.DESC()) # Tie-breaking: sort by count DESC, then apt_type_code DESC for 'Flat'
).CALCULATE(
    apt_type_code
)

ships_without_captains = Ship.WHERE(
    HASNOT(captains)
).CALCULATE(
    Name=name,
    Class=class
)

instructor_with_most_courses_building = faculties.CALCULATE(
    num_courses=COUNT(courses)
).TOP_K(1, by=[num_courses.DESC(), building.ASC()]).CALCULATE(
    building=building
)
